    tol = pybamm.settings.tolerances["j0__c_e"]
    c_e = pybamm.maximum(c_e, tol)
    tol = pybamm.settings.tolerances["j0__c_s"]
    c_s_surf = pybamm.maximum(
        pybamm.minimum(c_s_surf, (1 - tol) * self.c_max), tol * self.c_max
